{"path": "/app/deskstats/timeparse.py", "content": """"Every rule for reading dates and times lives here (docs/timeparse.md).

Nothing in this module reads the machine's clock or time zone.  Values that
Python cannot represent (an epoch of 1e30, a day number of 10**30) are
reported as ValueError, like text that cannot be read; the ValueError then
carries the error Python raised as its ``__cause__``.
"""

import itertools
import re
from datetime import date, datetime, time, timedelta, timezone, tzinfo

UTC = timezone.utc
SECONDS = "s"
MILLIS = "ms"
TRUNCATE = "truncate"
NEAREST_EVEN = "nearest_even"
YMD = "ymd"
DMY = "dmy"
MDY = "mdy"

_OFFSET = re.compile(r"([+-])(\d\d):(\d\d)")
_CONVERSION_ERRORS = (OverflowError, OSError)


class _Unrepresentable(ValueError):
    """A number that is read but that no date or time can hold."""


def parse_offset(text: str) -> timezone:
    """An offset as the site file writes it: +HH:MM or -HH:MM."""
    m = _OFFSET.fullmatch(text)
    if not m:
        raise ValueError(f"not an offset: {text!r}")
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-delta if m.group(1) == "-" else delta)


def _strptime(text: str, layout: str) -> datetime:
    """datetime.strptime, but %Z names the same zones on every machine (UTC and GMT)."""
    if not re.search(r"%Z", layout) or all(m.group(0) != "%Z" for m in re.finditer(r"%.?", layout, re.DOTALL)):
        return datetime.strptime(text, layout)
    count = sum(1 for m in re.finditer(r"%.?", layout, re.DOTALL) if m.group(0) == "%Z")
    for names in itertools.product(("UTC", "GMT"), repeat=count):
        it = iter(names)
        fixed = re.sub(r"%.?", lambda m: next(it) if m.group(0) == "%Z" else m.group(0), layout, flags=re.DOTALL)
        try:
            return datetime.strptime(text, fixed)
        except ValueError:
            pass
    raise ValueError(f"time data {text!r} does not match format {layout!r}")


def parse_instant(text: str, naive: tzinfo, layouts: tuple[str, ...] = ()) -> datetime:
    """An ISO 8601 time, else one of the layouts; a time without an offset is in `naive`."""
    text = text.strip()
    try:
        t = datetime.fromisoformat(text)
    except ValueError:
        for layout in layouts:
            try:
                t = _strptime(text, layout)
                break
            except ValueError:
                pass
        else:
            raise ValueError(f"not a time: {text!r}") from None
    if t.tzinfo is None:
        t = t.replace(tzinfo=naive)
    return t


def from_epoch(value: str | int | float, unit: str, method: str) -> datetime:
    """Unix time in `unit` as an aware UTC datetime on a whole second.

    The arithmetic is binary floating point: TRUNCATE cuts int(float(value))
    (the phone switch), NEAREST_EVEN rounds half to even (the chat service).
    """
    if unit not in (SECONDS, MILLIS):
        raise ValueError(f"unknown unit: {unit!r}")
    if method not in (TRUNCATE, NEAREST_EVEN):
        raise ValueError(f"unknown method: {method!r}")
    if isinstance(value, bool) or not isinstance(value, (str, int, float)):
        raise ValueError(f"not a number: {value!r}")
    try:
        if method == TRUNCATE:
            x = float(value)
            seconds = int(x / 1000 if unit == MILLIS else x)
        else:
            x = float(value) if isinstance(value, str) else value
            seconds = round(x / 1000 if unit == MILLIS else x)
        return datetime.fromtimestamp(seconds, tz=UTC)
    except _CONVERSION_ERRORS as e:
        raise _Unrepresentable(str(e)) from e


def parse_day(text: str, order: str) -> date:
    """A day: YMD as date.fromisoformat, DMY as HR writes it, MDY as facilities writes it."""
    if order == YMD:
        return date.fromisoformat(text)
    if order == DMY:
        # Day first; a two-digit year is in this century.
        d, m, y = text.split("/")
        year = int(y)
        if year < 100:
            year += 2000
        try:
            return date(year, int(m), int(d))
        except _CONVERSION_ERRORS as e:
            raise _Unrepresentable(str(e)) from e
    if order == MDY:
        return datetime.strptime(text, "%m/%d/%Y").date()
    raise ValueError(f"unknown order: {order!r}")


def at_clock(day: date, text: str, tz: tzinfo) -> datetime:
    """HH:MM on `day` in `tz`; 24:00 is the midnight that ends the day."""
    h, m = text.split(":")
    hour, minute = int(h), int(m)
    try:
        if (hour, minute) == (24, 0):
            return datetime.combine(day + timedelta(days=1), time(0), tz)
        return datetime(day.year, day.month, day.day, hour, minute, tzinfo=tz)
    except _CONVERSION_ERRORS as e:
        raise _Unrepresentable(str(e)) from e


def day_start(day: date, tz: tzinfo) -> datetime:
    """The midnight that starts `day` in `tz`."""
    return datetime.combine(day, time(0), tz)
