{"path": "/app/tests/test_timeparse.py", "content": """"The rules of deskstats.timeparse, on values of their own."""

import ast
import os
import time
import unittest
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

from deskstats import cli, timeparse as tp

PLUS1 = timezone(timedelta(hours=1))
PLUS530 = timezone(timedelta(hours=5, minutes=30))


class Offsets(unittest.TestCase):
    def test_offset(self):
        self.assertEqual(tp.parse_offset("+05:30"), PLUS530)
        self.assertEqual(tp.parse_offset("-00:30").utcoffset(None), timedelta(minutes=-30))
        self.assertIsNone(tp.parse_offset("+01:00").tzname(None) and None)
        for bad in ("+0100", "+1:00", " +01:00", "+01:00\n", "", "+24:00", "+99:99"):
            with self.assertRaises(ValueError, msg=bad):
                tp.parse_offset(bad)


class Instants(unittest.TestCase):
    def test_naive_gets_zone(self):
        self.assertEqual(tp.parse_instant(" 2026-03-02T09:15:02 ", tp.UTC), datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC))
        self.assertEqual(tp.parse_instant("2026-03-02T09:15:02", PLUS1).utcoffset(), timedelta(hours=1))

    def test_offset_kept(self):
        t = tp.parse_instant("20260302T101502.5+0530", PLUS1)
        self.assertEqual(t.utcoffset(), timedelta(hours=5, minutes=30))
        self.assertEqual(t.microsecond, 500000)

    def test_layouts(self):
        layouts = ("%Y-%m-%d %H:%M", "%d.%m.%Y %H:%M")
        self.assertEqual(tp.parse_instant("2026-3-2 9:05", PLUS1, layouts), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))
        self.assertEqual(tp.parse_instant("2.3.2026 9:05", PLUS1, layouts), datetime(2026, 3, 2, 9, 5, tzinfo=PLUS1))
        with self.assertRaises(ValueError):
            tp.parse_instant("2.3.2026 9:05", PLUS1)
        with self.assertRaises(ValueError):
            tp.parse_instant("", PLUS1, layouts)

    def test_zone_names_do_not_depend_on_machine(self):
        old = os.environ.get("TZ")
        try:
            os.environ["TZ"] = "America/New_York"
            time.tzset()
            with self.assertRaises(ValueError):
                tp.parse_instant("2026-03-02 09:05 EST", tp.UTC, ("%Y-%m-%d %H:%M %Z",))
            t = tp.parse_instant("2026-03-02 09:05 gmt", tp.UTC, ("%Y-%m-%d %H:%M %Z",))
            self.assertEqual(t, datetime(2026, 3, 2, 9, 5, tzinfo=tp.UTC))
        finally:
            if old is None:
                os.environ.pop("TZ", None)
            else:
                os.environ["TZ"] = old
            time.tzset()


class Epochs(unittest.TestCase):
    def test_truncate(self):
        t = datetime(2026, 3, 2, 9, 15, 2, tzinfo=tp.UTC)
        self.assertEqual(tp.from_epoch("1772442902.75", tp.SECONDS, tp.TRUNCATE), t)
        self.assertEqual(tp.from_epoch(1772442902.75, tp.SECONDS, tp.TRUNCATE), t)
        self.assertEqual(tp.from_epoch("-0.5", tp.SECONDS, tp.TRUNCATE), datetime(1970, 1, 1, tzinfo=tp.UTC))

    def test_nearest_even(self):
        self.assertEqual(tp.from_epoch(1500, tp.MILLIS, tp.NEAREST_EVEN).second, 2)
        self.assertEqual(tp.from_epoch(2500, tp.MILLIS, tp.NEAREST_EVEN).second, 2)
        self.assertEqual(tp.from_epoch("1772442902750", tp.MILLIS, tp.NEAREST_EVEN).second, 3)
        self.assertEqual(tp.from_epoch(2.5, tp.SECONDS, tp.NEAREST_EVEN).second, 2)

    def test_errors(self):
        for args in (("x", tp.SECONDS, tp.TRUNCATE), ("nan", tp.SECONDS, tp.TRUNCATE), ("inf", tp.SECONDS, tp.TRUNCATE),
                     ("1e30", tp.SECONDS, tp.TRUNCATE), (1e18, tp.MILLIS, tp.NEAREST_EVEN), (float("nan"), tp.MILLIS, tp.NEAREST_EVEN),
                     (1, "h", tp.TRUNCATE), (1, tp.SECONDS, "ceil"), (None, tp.SECONDS, tp.TRUNCATE)):
            with self.assertRaises(ValueError, msg=args):
                tp.from_epoch(*args)


class Days(unittest.TestCase):
    def test_orders(self):
        self.assertEqual(tp.parse_day("2026-03-06", tp.YMD), date(2026, 3, 6))
        self.assertEqual(tp.parse_day("9/3/26", tp.DMY), date(2026, 3, 9))
        self.assertEqual(tp.parse_day("9/3/-5", tp.DMY), date(1995, 3, 9))
        self.assertEqual(tp.parse_day("09/03/2026", tp.DMY), date(2026, 3, 9))
        self.assertEqual(tp.parse_day("03/08/2026", tp.MDY), date(2026, 3, 8))
        self.assertEqual(tp.parse_day("3/8/2026", tp.MDY), date(2026, 3, 8))

    def test_errors(self):
        for text, order in (("2026/03/06", tp.YMD), ("1/2", tp.DMY), ("31/02/26", tp.DMY), ("1/1/99999999999999999999", tp.DMY),
                            ("03/08/26", tp.MDY), ("2026-03-06", tp.MDY), ("1/1/1", "dmy2")):
            with self.assertRaises(ValueError, msg=text):
                tp.parse_day(text, order)


class Clocks(unittest.TestCase):
    def test_clock(self):
        day = date(2026, 3, 2)
        self.assertEqual(tp.at_clock(day, "22:30", PLUS1), datetime(2026, 3, 2, 22, 30, tzinfo=PLUS1))
        self.assertEqual(tp.at_clock(day, "24:00", PLUS1), datetime(2026, 3, 3, tzinfo=PLUS1))
        for bad in ("24:01", "25:00", "1:60", "10", "1:2:3", "-1:00"):
            with self.assertRaises(ValueError, msg=bad):
                tp.at_clock(day, bad, PLUS1)
        with self.assertRaises(ValueError):
            tp.at_clock(date.max, "24:00", PLUS1)

    def test_day_start(self):
        self.assertEqual(tp.day_start(date(2026, 3, 2), PLUS530), datetime(2026, 3, 2, tzinfo=PLUS530))


class Rules(unittest.TestCase):
    def test_public_names(self):
        public = sorted(n for n in vars(tp) if not n.startswith("_") and n not in ("date", "datetime", "time", "timedelta", "timezone", "tzinfo", "re", "itertools"))
        self.assertEqual(public, sorted(["UTC", "SECONDS", "MILLIS", "TRUNCATE", "NEAREST_EVEN", "YMD", "DMY", "MDY",
                                         "parse_offset", "parse_instant", "from_epoch", "parse_day", "at_clock", "day_start"]))

    def test_no_building_outside(self):
        banned_calls = {"strptime", "fromisoformat", "fromtimestamp", "utcfromtimestamp", "fromordinal", "fromisocalendar",
                        "combine", "timestamp", "datetime", "date", "time", "timezone"}
        banned_imports = {"time", "calendar", "email.utils"}
        for path in Path(tp.__file__).parent.glob("*.py"):
            if path.name == "timeparse.py":
                continue
            tree = ast.parse(path.read_text(encoding="utf-8"))
            for node in ast.walk(tree):
                if isinstance(node, ast.Call):
                    f = node.func
                    name = f.attr if isinstance(f, ast.Attribute) else getattr(f, "id", None)
                    self.assertNotIn(name, banned_calls, path.name)
                    if name == "replace":
                        self.assertFalse({k.arg for k in node.keywords} & {"year", "month", "day", "hour", "minute", "second", "microsecond", "tzinfo", "fold"}, path.name)
                if isinstance(node, ast.Import):
                    self.assertFalse({a.name for a in node.names} & banned_imports, path.name)
                if isinstance(node, ast.ImportFrom):
                    self.assertNotIn(node.module, banned_imports, path.name)

    def test_timeparse_imports_nothing_from_deskstats(self):
        tree = ast.parse(Path(tp.__file__).read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom):
                self.assertFalse((node.module or "").startswith("deskstats"))

    def test_window_bounds(self):
        class S:
            tz = PLUS530
        w = cli.window(S, date(2026, 3, 2), date.max)
        self.assertEqual(w.since, datetime(2026, 3, 2, tzinfo=PLUS530))
        self.assertEqual(w.until, datetime(9999, 12, 31, 23, 59, 59, tzinfo=PLUS530))


if __name__ == "__main__":
    unittest.main()
"}

